import{_ as l,o as t,c as o,a5 as p}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"845-Excel拆分合并工具","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["EXCEL批处理"],"标签":["Excel 批量处理软件","Excel合并拆分工具","基准列数据合并","按列拆分Excel数据","按行拆分 Excel 文件"]},"headers":[{"level":3,"title":"文件合并：","slug":"文件合并","link":"#文件合并","children":[]},{"level":3,"title":"文件拆分","slug":"文件拆分","link":"#文件拆分","children":[]},{"level":3,"title":"使用场景例子展示","slug":"使用场景例子展示","link":"#使用场景例子展示","children":[]},{"level":3,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[]},{"level":3,"title":"1 主界面区域","slug":"_1-主界面区域","link":"#_1-主界面区域","children":[]},{"level":3,"title":"2 按行拆分","slug":"_2-按行拆分","link":"#_2-按行拆分","children":[]},{"level":3,"title":"3 按列拆分","slug":"_3-按列拆分","link":"#_3-按列拆分","children":[]},{"level":3,"title":"4 按基准列拆分","slug":"_4-按基准列拆分","link":"#_4-按基准列拆分","children":[]},{"level":3,"title":"注意事项：","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]},{"level":3,"title":"📑 程序使用说明","slug":"📑-程序使用说明","link":"#📑-程序使用说明","children":[]}],"relativePath":"md/EXCEL批处理/845-Excel拆分合并工具.md","filePath":"md/EXCEL批处理/845-Excel拆分合并工具.md"}'),a={name:"md/EXCEL批处理/845-Excel拆分合并工具.md"};function r(n,e,s,c,i,d){return t(),o("div",null,[...e[0]||(e[0]=[p('<p>Excel 合并拆分工具，支持多份 Excel 文件按基准列以 “并集 / 交集” 模式合并（缺失值使用空白填充），也可将单个 Excel 文件按行范围、列范围、基准列分类拆分（支持拆分为多文件或同一文件的不同工作表），支持文件夹 / 文件拖拽选择。</p><h3 id="文件合并" tabindex="-1">文件合并： <a class="header-anchor" href="#文件合并" aria-label="Permalink to &quot;文件合并：&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251128233733176434425314675.png" alt=""></p><h3 id="文件拆分" tabindex="-1">文件拆分 <a class="header-anchor" href="#文件拆分" aria-label="Permalink to &quot;文件拆分&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251128233811176434429141010.jpg" alt=""></p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p><strong>场景 1：合并多份 Excel 通讯录数据（并集模式）</strong></p><p>**场景描述：**有 3 份 Excel 通讯录文件，分别记录不同部门的人员信息，列名包含 “姓名、电话、部门、地址”，部分人员信息在多份文件中重复，需要合并所有数据（保留所有人员，缺失字段空白填充），按 “姓名” 作为基准列对齐。</p><p>**操作步骤：**启动工具后切换到 “文件合并” 页，点击 “添加文件” 选择 3 份通讯录 Excel；基准列选择 “姓名”，合并模式选择 “并集”；点击 “开始合并”，选择桌面作为保存路径并命名为 “合并后通讯录.xlsx”；等待日志提示处理完成。</p><p>**预期结果：**生成的 Excel 文件包含所有人员信息，“姓名” 列对齐，不同文件中缺失的 “电话 / 地址” 等字段以空白填充，无重复姓名覆盖，日志清晰标注合并进度和文件数量。</p><p><strong>场景 2：按行拆分大体积 Excel 数据文件</strong></p><p>**场景描述：**有一个包含 5000 行销售数据的 Excel 文件，需要拆分为每份 1000 行的小文件，便于分发给不同同事处理，要求拆分为多个独立文件。</p><p>**操作步骤：**切换到 “文件拆分” 页，点击 “浏览...” 选择销售数据 Excel；拆分方式选择 “按行范围拆分”，每份行数填写 1000；输出方式选择 “拆分成多个文件”；点击 “开始拆分”，选择 “销售数据拆分” 文件夹作为输出目录；等待日志提示处理完成。</p><p>**预期结果：**输出目录中生成 5 个 Excel 文件，分别命名为 “销售数据_按行拆分_第 1 部分.xlsx” 至 “第 5 部分.xlsx”，前 4 份各 1000 行，最后 1 份 1000 行，数据完整无丢失，格式与原文件一致。</p><p><strong>场景 3：按基准列拆分客户分类数据（多工作表模式）</strong></p><p>**场景描述：**有一份包含 “客户名称、地区、销售额” 的 Excel 文件，需要按 “地区” 列拆分数据，将不同地区的客户数据保存到同一 Excel 文件的不同工作表中，便于集中查看。</p><p>**操作步骤：**切换到 “文件拆分” 页，拖拽选择客户数据 Excel；拆分方式选择 “按基准列分类”，基准列选择 “地区”；输出方式选择 “拆分到同一文件不同工作表”；点击 “开始拆分”，选择桌面作为输出目录；等待日志提示处理完成。</p><p>**预期结果：**生成的 Excel 文件中包含多个工作表，工作表名对应不同地区（如 “北京”“上海”），每个工作表仅显示对应地区的客户数据，工作表名自动规避非法字符，数据分类清晰。</p><h3 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h3><h3 id="_1-主界面区域" tabindex="-1">1 主界面区域 <a class="header-anchor" href="#_1-主界面区域" aria-label="Permalink to &quot;1 主界面区域&quot;">​</a></h3><p>界面主要分为两大功能页：</p><p><strong>合并页</strong></p><p>选择输入文件/文件夹（支持拖拽）</p><p>设置输出目录</p><p>配置合并规则（是否合并所有工作表、是否保留表头等）</p><p>点击“开始合并”执行</p><p><strong>拆分页</strong></p><p>选择要拆分的 Excel 文件（支持拖拽）</p><p>设置输出目录</p><p>选择拆分方式：</p><p><strong>按行拆分</strong></p><p><strong>按列拆分</strong></p><p><strong>按基准列拆分</strong></p><p>设置对应参数后点击“开始拆分”</p><p>底部为<strong>日志窗口</strong>，会详细记录每一步处理状态、文件名、错误信息等。</p><hr><h3 id="_2-按行拆分" tabindex="-1">2 按行拆分 <a class="header-anchor" href="#_2-按行拆分" aria-label="Permalink to &quot;2 按行拆分&quot;">​</a></h3><p>选择待拆分的 Excel 文件和输出目录</p><p>在“每份行数”中输入数字（例如：1000）</p><p>选择输出方式：</p><p><strong>拆分到同一文件不同工作表</strong>：生成 <code>源文件名_按行拆分_多工作表.xlsx</code></p><p><strong>拆分成多个文件</strong>：生成 <code>源文件名_按行拆分_第1部分.xlsx</code>、<code>第2部分.xlsx</code> …</p><p>点击“开始拆分”，在日志中查看进度和结果。</p><hr><h3 id="_3-按列拆分" tabindex="-1">3 按列拆分 <a class="header-anchor" href="#_3-按列拆分" aria-label="Permalink to &quot;3 按列拆分&quot;">​</a></h3><p>选择待拆分的 Excel 文件和输出目录</p><p>设置列范围（如 <code>A-Z</code>），以及每多少列为一组（例如：5）</p><p>选择输出方式：</p><p><strong>拆分到同一文件不同工作表</strong>：生成 <code>源文件名_按列拆分_多工作表.xlsx</code>，每组列一个工作表</p><p><strong>拆分成多个文件</strong>：生成 <code>源文件名_按列拆分_第1部分.xlsx</code> 等</p><p>点击“开始拆分”。</p><hr><h3 id="_4-按基准列拆分" tabindex="-1">4 按基准列拆分 <a class="header-anchor" href="#_4-按基准列拆分" aria-label="Permalink to &quot;4 按基准列拆分&quot;">​</a></h3><p>选择待拆分的 Excel 文件和输出目录</p><p>在“基准列”中输入列名（如 <code>地区</code>、<code>部门</code> 等，需与表头一致）</p><p>选择输出方式：</p><p><strong>拆分到同一文件不同工作表</strong></p><p>生成 <code>源文件名_按{基准列}拆分_多工作表.xlsx</code></p><p>每个基准列取值（分类）对应一个工作表，工作表名会自动做安全处理并截断到 31 字符</p><p><strong>拆分成多个文件</strong></p><p>生成多个文件，如 <code>源文件名_按地区拆分_北京.xlsx</code>、<code>…_上海.xlsx</code> 等</p><p>点击“开始拆分”。</p><h3 id="注意事项" tabindex="-1">注意事项： <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项：&quot;">​</a></h3><p><strong>文件格式</strong>：建议使用 <code>.xlsx</code> 格式；老的 <code>.xls</code> 建议先另存为 <code>.xlsx</code> 再处理。</p><p><strong>表头要求</strong>：合并与拆分操作默认以第一行为表头，请确保源文件结构一致。</p><p><strong>工作表名称长度</strong>：Excel 限制工作表名最长 31 个字符，程序会自动截断并过滤非法字符。</p><p><strong>大文件性能</strong>：对非常大的 Excel 文件进行拆分/合并时，请耐心等待，尽量不要频繁操作窗口。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>双击该快捷方式即可启动工具。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251129000056176434565662564.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2182.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2182.html</a></p>',77)])])}const x=l(a,[["render",r]]);export{h as __pageData,x as default};
